            key = (r,c, out[r][c])
            if key not in seen:
                seen.add(key)
                print(f"  out[{r},{c}]={out[r][c]} at rel (+{rel_r:+d},+{rel_c:+d})")

print(f"\nTotal cells around anchor (4,1): {len(seen)}")

# Now collect ALL relative patterns from ALL anchors
print("\nALL relative patterns:")
all_rels = {}
for r in range(grid_h):
    for c in range(grid_w):
        if inp[r][c] == 3:
            for dr in range(-5, 10):
                for dc in range(-5, 10):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < grid_h and 0 <= nc < grid_w:
                        val = out[nr][nc]
                        if val != 0:
                            key = (dr, dc, val)
                            all_rels[key] = 1

for key in sorted(all_rels.keys()):
    print(f"  {key}")
